Algoritmo SinLluvia
  Dimension dias[10] Como Entero;
  Para i <- 0 Hasta 9 Hacer
    Leer dias[i];
  FinPara
  Definir racha Como Entero <- 0;
  Definir masLarga Como Entero <- 0;
  Para Cada llovio En dias Hacer
    Si llovio = 0 Entonces
      racha <- racha + 1;
      Si racha > masLarga Entonces
        masLarga <- racha;
      FinSi
    Sino
      racha <- 0;
    FinSi
  FinPara
  Escribir masLarga;
FinAlgoritmo
